theorem margin_isClosed {V E : Type*} (src dst : E → V) (w : E → Factors)
    (lo hi : V → ℝ) (τ : ℝ) :
    IsClosed {z | BoxedMargin src dst w lo hi τ z}

theorem lifted_cycle_violation {T : ℝ → ℝ} {a b : ℝ}
    (hT : MonotoneOn T (Set.Ici 0)) (ha : 0 ≤ a) (hab : a ≤ b)
    (hbad : b < T a) : b < T b

theorem least_minimizes_monotone {V : Type*} {S : Set (V → ℝ)}
    {x : V → ℝ} (hx : IsLeast S x) {C : (V → ℝ) → ℝ}
    (hC : Monotone C) {y : V → ℝ} (hy : y ∈ S) : C x ≤ C y

